    static NSArray *valid = nil;
    if (!valid) {
        valid = [[NSArray alloc] initWithObjects:@"bool", @"integer", @"float", @"date", @"string", @"data", @"xml", @"json", @"dictionary", @"array", nil];
    }
    return [valid containsObject:t];
}

static NSString *PLUWantTypeName(NSString *expect) {
        if ([expect isEqualToString:@"bool"]) return @"boolean";
    return expect;
}

static NSArray *PLUKeyPathComponents(NSString *path) {
    NSMutableArray *comps = [NSMutableArray array];
    NSMutableString *cur = [NSMutableString string];
    NSUInteger len = path.length;
    for (NSUInteger i = 0; i < len; i++) {
        unichar c = [path characterAtIndex:i];
        if (c == '\\' && i + 1 < len) {
            [cur appendFormat:@"%C", [path characterAtIndex:++i]];
        } else if (c == '.') {
            [comps addObject:cur];
            cur = [NSMutableString string];
        } else {
            [cur appendFormat:@"%C", c];
        }
    }
    [comps addObject:cur];
    return comps;
}

static NSData *PLUReadData(NSString *path, NSString **errOut) {
    if ([path isEqualToString:@"-"] || [path isEqualToString:@"<stdin>"]) {
        NSData *d = [[NSFileHandle fileHandleWithStandardInput] readDataToEndOfFile];
        if (d.length == 0) {
            *errOut = @"(Unable to read file from standard input)";
            return nil;
        }
        return d;
    }
    NSData *d = nil;
    NSError *e = nil;
    d = [NSData dataWithContentsOfFile:path options:0 error:&e];
    if (!d) {
        *errOut = [NSString stringWithFormat:@"(%@)", [e localizedDescription]];
        return nil;
    }
    return d;
}

static id PLUParseData(NSData *data, NSPropertyListFormat *fmtOut, NSString **errOut) {
    NSError *e = nil;
    id obj = [NSPropertyListSerialization propertyListWithData:data
                                                       options:NSPropertyListMutableContainers
                                                        format:fmtOut
                                                         error:&e];
    if (obj) return obj;

    NSString *plistDebug = [e.userInfo objectForKey:@"NSDebugDescription"];
    NSError *je = nil;
    obj = [NSJSONSerialization JSONObjectWithData:data options:NSJSONReadingMutableContainers error:&je];
    if (obj) {
        *fmtOut = PLU_JSON_FORMAT;
        return obj;
    }
    NSString *jsonDebug = [je.userInfo objectForKey:@"NSDebugDescription"];
    *errOut = [NSString stringWithFormat:@"Property List error: %@ / JSON error: %@",
               plistDebug ?: @"(null)", jsonDebug ?: @"(null)"];
    return nil;
}

static NSString *PLULintDebug(NSData *data) {
    NSPropertyListFormat fmt;
    NSError *e = nil;
    id obj = [NSPropertyListSerialization propertyListWithData:data options:0 format:&fmt error:&e];
    if (obj) return nil;
    return [e.userInfo objectForKey:@"NSDebugDescription"];
}

static BOOL PLUIsBool(id v) {
    return CFGetTypeID((CFTypeRef)v) == CFBooleanGetTypeID();
}

static BOOL PLUIsFloatNumber(id v) {
    if (![v isKindOfClass:[NSNumber class]]) return NO;
    if (PLUIsBool(v)) return NO;
    return CFNumberIsFloatType((CFNumberRef)v);
}

static NSString *PLUTypeName(id v) {
    if ([v isKindOfClass:[NSString class]]) return @"string";
    if ([v isKindOfClass:[NSData class]]) return @"data";
    if ([v isKindOfClass:[NSDate class]]) return @"date";
    if ([v isKindOfClass:[NSNumber class]]) {
        if (PLUIsBool(v)) return @"bool";
        if (PLUIsFloatNumber(v)) return @"float";
        return @"integer";
    }
    if ([v isKindOfClass:[NSArray class]]) return @"array";
    if ([v isKindOfClass:[NSDictionary class]]) return @"dictionary";
    if ([v isKindOfClass:[NSNull class]]) return @"null";
    return @"unknown";
}

static NSArray *PLUSortedKeys(NSDictionary *d) {
    NSArray *keys = [d allKeys];
    return [keys sortedArrayUsingComparator:^NSComparisonResult(id a, id b) {
        return [(NSString *)a compare:(NSString *)b
                              options:(NSCaseInsensitiveSearch | NSNumericSearch | NSForcedOrderingSearch)
                                range:NSMakeRange(0, [(NSString *)a length])
                               locale:[NSLocale systemLocale]];
    }];
}

static id PLUSortedCopy(id obj) {
    if ([obj isKindOfClass:[NSDictionary class]]) {
        NSMutableDictionary *m = [NSMutableDictionary dictionaryWithCapacity:[obj count]];
        for (NSString *key in PLUSortedKeys(obj)) {
            [m setObject:PLUSortedCopy([obj objectForKey:key]) forKey:key];
        }
        return m;
    }
    if ([obj isKindOfClass:[NSArray class]]) {
        NSMutableArray *m = [NSMutableArray arrayWithCapacity:[obj count]];
        for (id v in obj) [m addObject:PLUSortedCopy(v)];
        return m;
    }
    return obj;
}

static NSData *PLUPropertyListData(id obj, NSPropertyListFormat fmt, BOOL *ok) {
    CFPropertyListFormat cff;
    switch (fmt) {
        case NSPropertyListXMLFormat_v1_0:
            cff = kCFPropertyListXMLFormat_v1_0;
            break;
        case NSPropertyListBinaryFormat_v1_0:
            cff = kCFPropertyListBinaryFormat_v1_0;
            break;
        case NSPropertyListOpenStepFormat:
            cff = kCFPropertyListOpenStepFormat;
            break;
        default:
            *ok = NO;
            return nil;
    }
    id sorted = PLUSortedCopy(obj);
    CFDataRef cf = CFPropertyListCreateData(kCFAllocatorDefault, (CFPropertyListRef)sorted, cff, 0, NULL);
    if (!cf) {
        *ok = NO;
        return nil;
    }
    *ok = YES;
    return [(id)cf autorelease];
}

static NSData *PLUJSONData(id obj, BOOL pretty, BOOL *ok) {
    if (![obj isKindOfClass:[NSDictionary class]] && ![obj isKindOfClass:[NSArray class]]) {
        *ok = NO;
        return nil;
    }
    NSJSONWritingOptions o = (pretty) ? (NSJSONWritingPrettyPrinted | NSJSONWritingSortedKeys) : 0;
    NSError *e = nil;
    NSData *d = nil;
    @try {
        d = [NSJSONSerialization dataWithJSONObject:obj options:o error:&e];
    } @catch (NSException *ex) {
        d = nil;
    }
    if (!d) {
        *ok = NO;
        return nil;
    }
    *ok = YES;
    return d;
}

static void PLUWriteStdoutData(NSData *d) {
    fwrite(d.bytes, 1, d.length, stdout);
}

static int PLUWriteFileData(NSString *src, NSString *path, NSData *d) {
    NSError *e = nil;
    if ([d writeToFile:path options:0 error:&e]) return 0;
    if (src) fprintf(stderr, "%s: (%s)\n", [src UTF8String], [[e localizedDescription] UTF8String]);
    else fprintf(stderr, "(%s)\n", [[e localizedDescription] UTF8String]);
    return 1;
}

static void PLUAppendSpaces(NSMutableString *s, NSUInteger n) {
    for (NSUInteger i = 0; i < n; i++) [s appendString:@"    "];
}

static NSString *PLUEscapeSwift(NSString *s) {
    NSMutableString *m = [NSMutableString stringWithCapacity:s.length];
    for (NSUInteger i = 0; i < s.length; i++) {
        unichar c = [s characterAtIndex:i];
        if (c == '"') [m appendString:@"\\\""];
        else if (c == '\\') [m appendString:@"\\\\"];
        else if (c == '\n') [m appendString:@"\\n"];
        else [m appendFormat:@"%C", c];
    }
    return m;
}

static NSString *PLUEscapeObjC(NSString *s) {
    NSMutableString *m = [NSMutableString stringWithCapacity:s.length];
    for (NSUInteger i = 0; i < s.length; i++) {
        unichar c = [s characterAtIndex:i];
        if (c == '"') [m appendString:@"\\\""];
        else if (c == '\\') [m appendString:@"\\\\"];
        else [m appendFormat:@"%C", c];
    }
    return m;
}

static NSString *PLURawString(id v) {
    if ([v isKindOfClass:[NSString class]]) return v;
    if ([v isKindOfClass:[NSData class]]) return [v base64EncodedStringWithOptions:0];
    if ([v isKindOfClass:[NSDate class]]) {
        static NSISO8601DateFormatter *fmt = nil;
        if (!fmt) {
            fmt = [[NSISO8601DateFormatter alloc] init];
        }
        return [fmt stringFromDate:v];
    }
    if ([v isKindOfClass:[NSNumber class]]) {
        if (PLUIsBool(v)) return [(NSNumber *)v boolValue] ? @"true" : @"false";
        if (PLUIsFloatNumber(v)) return [NSString stringWithFormat:@"%f", [v doubleValue]];
        return [NSString stringWithFormat:@"%lld", [v longLongValue]];
    }
    if ([v isKindOfClass:[NSArray class]]) return [NSString stringWithFormat:@"%ld", (long)[v count]];
    if ([v isKindOfClass:[NSDictionary class]]) {
        NSMutableArray *parts = [NSMutableArray array];
        for (NSString *k in PLUSortedKeys(v)) [parts addObject:k];
        return [parts componentsJoinedByString:@"\n"];
    }
    if ([v isKindOfClass:[NSNull class]]) return @"";
    return [v description];
}

static NSString *PLUScalarPrint(id v);

static void PLUPrintAppendObject(NSMutableString *out, id obj, NSString *closeIndent) {
    if ([obj isKindOfClass:[NSDictionary class]]) {
        [out appendString:@"{\n"];
        NSString *next = [closeIndent stringByAppendingString:@"  "];
        for (NSString *key in PLUSortedKeys(obj)) {
            [out appendFormat:@"%@\"%@\" => ", next, key];
            id v = [obj objectForKey:key];
            if ([v isKindOfClass:[NSDictionary class]] || [v isKindOfClass:[NSArray class]]) {
                PLUPrintAppendObject(out, v, next);
                [out appendString:@"\n"];
            } else {
                [out appendString:PLUScalarPrint(v)];
                [out appendString:@"\n"];
            }
        }
        [out appendFormat:@"%@}", closeIndent];
    } else if ([obj isKindOfClass:[NSArray class]]) {
        [out appendString:@"[\n"];
        NSString *next = [closeIndent stringByAppendingString:@"  "];
        NSUInteger i = 0;
        for (id v in obj) {
            [out appendFormat:@"%@%lu => ", next, (unsigned long)i];
            if ([v isKindOfClass:[NSDictionary class]] || [v isKindOfClass:[NSArray class]]) {
                PLUPrintAppendObject(out, v, next);
                [out appendString:@"\n"];
            } else {
                [out appendString:PLUScalarPrint(v)];
                [out appendString:@"\n"];
            }
            i++;
        }
        [out appendFormat:@"%@]", closeIndent];
    } else {
        [out appendString:PLUScalarPrint(obj)];
    }
}

static NSString *PLUScalarPrint(id v) {
    if ([v isKindOfClass:[NSString class]]) {
        return [NSString stringWithFormat:@"\"%@\"", v];
    }
    if ([v isKindOfClass:[NSNumber class]]) {
        if (PLUIsBool(v)) return [(NSNumber *)v boolValue] ? @"true" : @"false";
        return [v description];
    }
    return [v description];
}

static NSString *PLUPrintText(id obj) {
    NSMutableString *s = [NSMutableString string];
    PLUPrintAppendObject(s, obj, @"");
    [s appendString:@"\n"];
    return s;
}

static NSString *PLUExtractValue(id root, NSString *path, NSString **errOut) {
    NSArray *comps = PLUKeyPathComponents(path);
    id cur = root;
    for (NSString *comp in comps) {
        if ([cur isKindOfClass:[NSDictionary class]]) {
            id v = [cur objectForKey:comp];
            if (v == nil) {
                *errOut = [NSString stringWithFormat:@"No value at that key path or invalid key path: %@", path];
                return nil;
            }
            cur = v;
        } else if ([cur isKindOfClass:[NSArray class]]) {
            NSInteger idx = [comp integerValue];
            if (idx < 0 || idx >= (NSInteger)[cur count]) {
                *errOut = [NSString stringWithFormat:@"No value at that key path or invalid key path: %@", path];
                return nil;
            }
            cur = [cur objectAtIndex:idx];
        } else {
            *errOut = [NSString stringWithFormat:@"No value at that key path or invalid key path: %@", path];
            return nil;
        }
    }
    return cur;
}

static BOOL PLUIsNumericString(NSString *s) {
    if (s.length == 0) return NO;
    for (NSUInteger i = 0; i < s.length; i++) {
        unichar c = [s characterAtIndex:i];
        if (c < '0' || c > '9') return NO;
    }
    return YES;
}

static int PLUTreemutate(id root, NSString *path, id value, BOOL replace, BOOL append, NSString **errOut) {
    NSArray *comps = PLUKeyPathComponents(path);
    id cur = root;
    NSUInteger count = comps.count;
    for (NSUInteger i = 0; i < count; i++) {
        NSString *comp = [comps objectAtIndex:i];
        BOOL last = (i == count - 1);
        if ([cur isKindOfClass:[NSDictionary class]]) {
            if (last) {
                id existing = [cur objectForKey:comp];
                if (!replace && append) {
                    if ([existing isKindOfClass:[NSMutableArray class]]) {
                        [existing addObject:value];
                        return 0;
                    }
                    if (existing) {
                        *errOut = [NSString stringWithFormat:@"Appending to a non-array at key path %@", path];
                        return -1;
                    }
                }
                if (existing && !replace) {
                    *errOut = [NSString stringWithFormat:@"Value already exists at key path %@", path];
                    return -1;
                }
                [cur setObject:value forKey:comp];
                return 0;
            }
            id next = [cur objectForKey:comp];
            if (next == nil) {
                *errOut = [NSString stringWithFormat:@"Key path not found %@", path];
                return -1;
            }
            cur = next;
        } else if ([cur isKindOfClass:[NSArray class]]) {
            if (!PLUIsNumericString(comp)) {
                *errOut = [NSString stringWithFormat:@"Unable to insert value at key path %@", path];
                return -1;
            }
            NSInteger idx = comp.integerValue;
            if (last) {
                NSInteger max = (NSInteger)[cur count];
                if (idx < 0 || idx > max) {
                    *errOut = [NSString stringWithFormat:@"Index %ld out of bounds in array at key path %@", (long)idx, path];
                    return -1;
                }
                [cur insertObject:value atIndex:idx];
                return 0;
            }
            if (idx < 0 || idx >= (NSInteger)[cur count]) {
                *errOut = [NSString stringWithFormat:@"Index %ld out of bounds in array at key path %@", (long)idx, path];
                return -1;
            }
            cur = [cur objectAtIndex:idx];
        } else {
            *errOut = [NSString stringWithFormat:@"Unable to insert value at key path %@", path];
            return -1;
        }
    }
    *errOut = [NSString stringWithFormat:@"Unable to insert value at key path %@", path];
    return -1;
}

static int PLUTreeremove(id root, NSString *path, NSString **errOut) {
    NSArray *comps = PLUKeyPathComponents(path);
    id cur = root;
    NSUInteger count = comps.count;
    for (NSUInteger i = 0; i < count; i++) {
        NSString *comp = [comps objectAtIndex:i];
        BOOL last = (i == count - 1);
        if ([cur isKindOfClass:[NSDictionary class]]) {
            if (last) {
                if ([cur objectForKey:comp] == nil) {
                    *errOut = [NSString stringWithFormat:@"No value to remove at key path %@", path];
                    return -1;
                }
                [cur removeObjectForKey:comp];
                return 0;
            }
            id next = [cur objectForKey:comp];
            if (next == nil) {
                *errOut = [NSString stringWithFormat:@"Key path not found %@", path];
                return -1;
            }
            cur = next;
        } else if ([cur isKindOfClass:[NSArray class]]) {
            if (!PLUIsNumericString(comp)) {
                *errOut = [NSString stringWithFormat:@"No value to remove at key path %@", path];
                return -1;
            }
            NSInteger idx = comp.integerValue;
            if (last) {
                if (idx < 0 || idx >= (NSInteger)[cur count]) {
                    *errOut = [NSString stringWithFormat:@"No value to remove at key path %@", path];
                    return -1;
                }
                [cur removeObjectAtIndex:idx];
                return 0;
            }
            if (idx < 0 || idx >= (NSInteger)[cur count]) {
                *errOut = [NSString stringWithFormat:@"Index %ld out of bounds in array at key path %@", (long)idx, path];
                return -1;
            }
            cur = [cur objectAtIndex:idx];
        } else {
            *errOut = [NSString stringWithFormat:@"No value to remove at key path %@", path];
            return -1;
        }
    }
    *errOut = [NSString stringWithFormat:@"No value to remove at key path %@", path];
    return -1;
}

static id PLUValueForType(NSString *type, NSString *value) {
    if ([type isEqualToString:@"string"]) {
        return value;
    }
    if ([type isEqualToString:@"integer"]) {
        return [NSNumber numberWithLongLong:value.longLongValue];
    }
    if ([type isEqualToString:@"float"]) {
        return [NSNumber numberWithDouble:value.doubleValue];
    }
    if ([type isEqualToString:@"bool"]) {
        NSString *low = [value lowercaseString];
        if ([low isEqualToString:@"true"] || [low isEqualToString:@"yes"]) return (__bridge id)kCFBooleanTrue;
        return (__bridge id)kCFBooleanFalse;
    }
    if ([type isEqualToString:@"date"]) {
        static NSISO8601DateFormatter *fmt = nil;
        if (!fmt) {
            fmt = [[NSISO8601DateFormatter alloc] init];
        }
        NSDate *d = [fmt dateFromString:value];
        if (!d) {
            __builtin_trap();
        }
        return d;
    }
    if ([type isEqualToString:@"data"]) {
        return [[NSData alloc] initWithBase64EncodedString:value options:0];
    }
    if ([type isEqualToString:@"xml"]) {
        NSString *err = nil;
        NSPropertyListFormat f;
        id o = PLUParseData([value dataUsingEncoding:NSUTF8StringEncoding], &f, &err);
        return o;
    }
    if ([type isEqualToString:@"json"]) {
        NSError *e = nil;
        id o = [NSJSONSerialization JSONObjectWithData:[value dataUsingEncoding:NSUTF8StringEncoding]
                                               options:NSJSONReadingMutableContainers error:&e];
        return o;
    }
    if ([type isEqualToString:@"dictionary"]) {
        return [NSMutableDictionary dictionary];
    }
    if ([type isEqualToString:@"array"]) {
        return [NSMutableArray array];
    }
    return value;
}

static NSString *PLUSymbolForPath(NSString *dp) {
    NSString *leaf = [dp lastPathComponent];
    NSMutableString *base;
    if ([leaf isEqualToString:@"-"] || leaf.length == 0) {
        base = [NSMutableString stringWithString:@"_"];
    } else {
        base = [NSMutableString stringWithString:[leaf stringByDeletingPathExtension]];
    }
    NSMutableString *m = [NSMutableString stringWithCapacity:base.length];
    for (NSUInteger i = 0; i < base.length; i++) {
        unichar c = [base characterAtIndex:i];
        if (isalnum(c) || c == '_' || c == '.') {
            [m appendFormat:@"%C", c];
        } else {
            [m appendString:@"_"];
        }
    }
    if (m.length == 0) [m appendString:@"_"];
    return m;
}

static BOOL PLUSwiftAnnotate(id obj) {
    if (![obj isKindOfClass:[NSDictionary class]]) return NO;
    NSMutableSet *tokens = [NSMutableSet set];
    for (NSString *key in PLUSortedKeys(obj)) {
        id v = [obj objectForKey:key];
        if ([v isKindOfClass:[NSNumber class]]) {
            if (PLUIsBool(v)) [tokens addObject:@"num-bool"];
            else if (PLUIsFloatNumber(v)) [tokens addObject:@"num-float"];
            else [tokens addObject:@"num-int"];
        } else {
            [tokens addObject:NSStringFromClass([v class])];
        }
    }
    return tokens.count > 1;
}

static void PLUSwiftTokenAppend(NSMutableString *out, id v, NSUInteger depth, BOOL *fail) {
    if ([v isKindOfClass:[NSDictionary class]]) {
        [out appendString:@"[\n"];
        for (NSString *key in PLUSortedKeys(v)) {
            PLUAppendSpaces(out, depth + 1);
            [out appendFormat:@"\"%@\" : ", PLUEscapeSwift(key)];
            PLUSwiftTokenAppend(out, [v objectForKey:key], depth + 1, fail);
            if (*fail) return;
            [out appendString:@",\n"];
        }
        PLUAppendSpaces(out, depth);
        [out appendString:@"]"];
    } else if ([v isKindOfClass:[NSArray class]]) {
        [out appendString:@"[\n"];
        for (id item in v) {
            PLUAppendSpaces(out, depth + 1);
            PLUSwiftTokenAppend(out, item, depth + 1, fail);
            if (*fail) return;
            [out appendString:@",\n"];
        }
        PLUAppendSpaces(out, depth);
        [out appendString:@"]"];
    } else if ([v isKindOfClass:[NSNull class]]) {
        *fail = YES;
    } else if ([v isKindOfClass:[NSString class]]) {
        [out appendFormat:@"\"%@\"", PLUEscapeSwift(v)];
    } else if ([v isKindOfClass:[NSNumber class]]) {
        if (PLUIsBool(v)) [out appendString:[(NSNumber *)v boolValue] ? @"true" : @"false"];
        else if (PLUIsFloatNumber(v)) [out appendFormat:@"%f", [v doubleValue]];
        else [out appendFormat:@"%lld", [v longLongValue]];
    } else if ([v isKindOfClass:[NSData class]]) {
        [out appendString:@"Data(bytes: ["];
        const unsigned char *bytes = (const unsigned char *)[(NSData *)v bytes];
        for (NSUInteger i = 0; i < [(NSData *)v length]; i++) {
            [out appendFormat:@"0x%02X,", bytes[i]];
        }
        [out appendString:@"])"];
    } else if ([v isKindOfClass:[NSDate class]]) {
        [out appendFormat:@"Date(timeIntervalSinceReferenceDate: %.1f)", [(NSDate *)v timeIntervalSinceReferenceDate]];
    } else {
        *fail = YES;
    }
}

static NSString *PLUSwiftText(id obj, NSString *dp, NSString *symbol, BOOL annotate, BOOL withNewline) {
    NSMutableString *s = [NSMutableString string];
    [s appendFormat:@"/// Generated from %@\n", dp];
    [s appendFormat:@"let %@", symbol];
    if (annotate) [s appendString:@" : [String : Any]"];
    [s appendString:@" = "];
    BOOL fail = NO;
    PLUSwiftTokenAppend(s, obj, 0, &fail);
    if (fail) return nil;
    if (withNewline) [s appendString:@"\n"];
    return s;
}

static void PLUSObjCTokenAppend(NSMutableString *out, id v, NSUInteger depth, BOOL *fail) {
    if ([v isKindOfClass:[NSDictionary class]]) {
        [out appendString:@"@{\n"];
        for (NSString *key in PLUSortedKeys(v)) {
            PLUAppendSpaces(out, depth + 1);
            [out appendFormat:@"@\"%@\" : ", PLUEscapeObjC(key)];
            PLUSObjCTokenAppend(out, [v objectForKey:key], depth + 1, fail);
            if (*fail) return;
            [out appendString:@",\n"];
        }
        PLUAppendSpaces(out, depth);
        [out appendString:@"}"];
    } else if ([v isKindOfClass:[NSArray class]]) {
        [out appendString:@"@[\n"];
        for (id item in v) {
            PLUAppendSpaces(out, depth + 1);
            PLUSObjCTokenAppend(out, item, depth + 1, fail);
            if (*fail) return;
            [out appendString:@",\n"];
        }
        PLUAppendSpaces(out, depth);
        [out appendString:@"]"];
    } else if ([v isKindOfClass:[NSNull class]] || [v isKindOfClass:[NSDate class]] || [v isKindOfClass:[NSData class]]) {
        *fail = YES;
    } else if ([v isKindOfClass:[NSString class]]) {
        [out appendFormat:@"@\"%@\"", PLUEscapeObjC(v)];
    } else if ([v isKindOfClass:[NSNumber class]]) {
        if (PLUIsBool(v)) [out appendString:[(NSNumber *)v boolValue] ? @"@YES" : @"@NO"];
        else if (PLUIsFloatNumber(v)) [out appendFormat:@"@%f", [v doubleValue]];
        else [out appendFormat:@"@%lld", [v longLongValue]];
    } else {
        *fail = YES;
    }
}

static NSString *PLUObjCDeclaration(id obj, NSString *symbol) {
    if ([obj isKindOfClass:[NSArray class]]) {
        return [NSString stringWithFormat:@"NSArray * const %@", symbol];
    }
    if ([obj isKindOfClass:[NSString class]]) {
        return [NSString stringWithFormat:@"NSString * const %@", symbol];
    }
    if ([obj isKindOfClass:[NSNumber class]]) {
        return [NSString stringWithFormat:@"NSNumber * const %@", symbol];
    }
    return [NSString stringWithFormat:@"NSDictionary * const %@", symbol];
}

static NSString *PLUObjCText(id obj, NSString *dp, NSString *symbol, NSString *importBase) {
    NSMutableString *s = [NSMutableString string];
    if (importBase) {
        [s appendFormat:@"#import \"%@.h\"\n\n", importBase];
    }
    [s appendFormat:@"/// Generated from %@\n", dp];
    [s appendString:@"__attribute__((visibility(\"hidden\")))\n"];
    [s appendFormat:@"%@ = ", PLUObjCDeclaration(obj, symbol)];
    BOOL fail = NO;
    PLUSObjCTokenAppend(s, obj, 0, &fail);
    if (fail) return nil;
    [s appendFormat:@";\n"];
    return s;
}

static NSString *PLUObjCHeaderText(id obj, NSString *dp, NSString *symbol) {
    NSMutableString *s = [NSMutableString string];
    [s appendString:@"#import <Foundation/Foundation.h>\n\n"];
    [s appendFormat:@"/// Generated from %@\n", dp];
    [s appendString:@"__attribute__((visibility(\"hidden\")))\n"];
    [s appendFormat:@"extern %@;\n", PLUObjCDeclaration(obj, symbol)];
    return s;
}

static BOOL PLUIsKnownFormat(NSString *fmt, BOOL forExtract) {
    static NSSet *set = nil;
    static NSSet *eset = nil;
    if (!set) {
        set = [[NSSet alloc] initWithObjects:@"xml1", @"binary1", @"json", @"swift", @"objc", nil];
        eset = [[NSSet alloc] initWithObjects:@"xml1", @"binary1", @"json", @"swift", @"objc", @"raw", nil];
    }
    return [forExtract ? eset : set containsObject:fmt];
}

static int PLUHandleLint(PLUOptions O, NSArray *files) {
    int rc = 0;
    for (NSString *dp in files) {
        NSString *err = nil;
        NSData *data = PLUReadData(dp, &err);
        if (!data) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        NSString *debug = PLULintDebug(data);
        if (debug) {
            fprintf(stderr, "%s: (%s)\n", [dp UTF8String], [debug UTF8String]);
            rc = 1;
        } else if (!O.silent) {
            printf("%s: OK\n", [dp UTF8String]);
        }
    }
    return rc;
}

static int PLUHandlePrint(PLUOptions O, NSArray *files) {
    (void)O;
    int rc = 0;
    for (NSString *dp in files) {
        NSString *err = nil;
        NSData *data = PLUReadData(dp, &err);
        if (!data) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        NSPropertyListFormat fmt;
        id obj = PLUParseData(data, &fmt, &err);
        if (!obj) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        fputs([PLUPrintText(obj) UTF8String], stdout);
    }
    return rc;
}

static NSString *PLUResolveTarget(PLUOptions O, NSString *dp, NSString *defaultTarget) {
    if (O.outPath) return O.outPath;
    if (O.outExt) return [[dp stringByDeletingPathExtension] stringByAppendingFormat:@".%@", O.outExt];
    return defaultTarget;
}

static int PLUWriteBinaryTarget(NSString *src, NSString *target, BOOL toStdout, NSData *data) {
    if (toStdout) {
        PLUWriteStdoutData(data);
        return 0;
    }
    return PLUWriteFileData(src, target, data);
}

static int PLUHandleRawOrTypeOutput(NSString *text, PLUOptions O, BOOL toStdout, NSString *target, NSString *src) {
    (void)O;
    NSMutableString *s = [NSMutableString stringWithString:text];
    if (toStdout && !O.noNL) [s appendString:@"\n"];
    if (toStdout) {
        fputs([s UTF8String], stdout);
        return 0;
    }
    return PLUWriteFileData(src, target, [s dataUsingEncoding:NSUTF8StringEncoding]);
}

static NSString *PLUDefaultExtractTarget(NSString *fmt, NSString *dp) {
    if ([fmt isEqualToString:@"swift"]) return [[dp stringByDeletingPathExtension] stringByAppendingPathExtension:@"swift"];
    if ([fmt isEqualToString:@"objc"]) return [[dp stringByDeletingPathExtension] stringByAppendingPathExtension:@"m"];
    if ([fmt isEqualToString:@"raw"]) return nil;
    return dp;
}

static int PLUHandleExtract(PLUOptions O, NSString *keyPath, NSString *fmt, NSArray *files) {
    if (!PLUIsKnownFormat(fmt, YES)) {
        fprintf(stderr, "Unknown format specifier: %s\n", [fmt UTF8String]);
        return 1;
    }
    int rc = 0;
    for (NSString *dp in files) {
        NSString *err = nil;
        NSData *data = PLUReadData(dp, &err);
        if (!data) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        NSPropertyListFormat pfmt;
        id root = PLUParseData(data, &pfmt, &err);
        if (!root) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        id v = PLUExtractValue(root, keyPath, &err);
        if (!v) {
            fprintf(stderr, "%s: Could not extract value, error: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        if (O.expect) {
            NSString *want = PLUWantTypeName(O.expect);
            if (want && ![want isEqualToString:PLUTypeName(v)]) {
                fprintf(stderr, "%s: Value at [%s] expected to be %s but is %s\n",
                        [dp UTF8String], [keyPath UTF8String], [want UTF8String], [PLUTypeName(v) UTF8String]);
                rc = 1;
                continue;
            }
        }

        NSString *defaultTarget = PLUDefaultExtractTarget(fmt, dp);
        if ([fmt isEqualToString:@"raw"]) {
            NSString *target = PLUResolveTarget(O, dp, nil);
            BOOL toStdout = (target == nil || [target isEqualToString:@"-"]);
            rc |= PLUHandleRawOrTypeOutput(PLURawString(v), O, toStdout, target, dp);
            continue;
        }
        if ([fmt isEqualToString:@"json"]) {
            BOOL ok = NO;
            NSData *d = PLUJSONData(v, O.pretty, &ok);
            if (!ok) {
                fprintf(stderr, "%s: Invalid object in plist for JSON format\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            NSString *target = PLUResolveTarget(O, dp, defaultTarget);
            BOOL toStdout = (target == nil || [target isEqualToString:@"-"]);
            rc |= PLUWriteBinaryTarget(dp, target, toStdout, d);
            continue;
        }
        if ([fmt isEqualToString:@"xml1"] || [fmt isEqualToString:@"binary1"]) {
            NSPropertyListFormat wfmt;
            BOOL ok = NO;
            if ([fmt isEqualToString:@"xml1"]) wfmt = NSPropertyListXMLFormat_v1_0;
            else wfmt = NSPropertyListBinaryFormat_v1_0;
            NSData *d = PLUPropertyListData(v, wfmt, &ok);
            if (!ok) {
                fprintf(stderr, "%s: Could not serialize property list\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            NSString *target = PLUResolveTarget(O, dp, defaultTarget);
            BOOL toStdout = (target == nil || [target isEqualToString:@"-"]);
            rc |= PLUWriteBinaryTarget(dp, target, toStdout, d);
            continue;
        }
        if ([fmt isEqualToString:@"swift"]) {
            NSString *symbol = PLUSymbolForPath(dp);
            NSString *text = PLUSwiftText(v, dp, symbol, PLUSwiftAnnotate(v), YES);
            if (!text) {
                fprintf(stderr, "%s: Input contains an object that cannot be represented in Swift literal syntax\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            NSString *target = PLUResolveTarget(O, dp, defaultTarget);
            BOOL toStdout = (O.outPath && [O.outPath isEqualToString:@"-"]);
            if (toStdout) {
                fputs([text UTF8String], stdout);
            } else {
                rc |= PLUWriteFileData(dp, target, [text dataUsingEncoding:NSUTF8StringEncoding]);
            }
            continue;
        }
        if ([fmt isEqualToString:@"objc"]) {
            NSString *symbol = PLUSymbolForPath(dp);
            NSString *target = PLUResolveTarget(O, dp, defaultTarget);
            BOOL toStdout = (O.outPath && [O.outPath isEqualToString:@"-"]);
            NSString *importBase = (target && !toStdout) ? [target lastPathComponent] : nil;
            NSString *text = PLUObjCText(v, dp, symbol, importBase);
            if (!text) {
                fprintf(stderr, "%s: Input contains an object that cannot be represented in Obj-C literal syntax\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            if (toStdout) {
                fputs([text UTF8String], stdout);
            } else {
                rc |= PLUWriteFileData(dp, target, [text dataUsingEncoding:NSUTF8StringEncoding]);
            }
        }
    }
    return rc;
}

static int PLUHandleConvert(PLUOptions O, NSString *fmt, NSArray *files) {
    if (!PLUIsKnownFormat(fmt, NO)) {
        fprintf(stderr, "Unknown format specifier: %s\n", [fmt UTF8String]);
        return 1;
    }
    if (O.header && ![fmt isEqualToString:@"objc"]) {
        fprintf(stderr, "-header is only valid for objc literal conversions.\n");
        return 1;
    }
    int rc = 0;
    for (NSString *dp in files) {
        NSString *err = nil;
        NSData *data = PLUReadData(dp, &err);
        if (!data) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        NSPropertyListFormat pfmt;
        id obj = PLUParseData(data, &pfmt, &err);
        if (!obj) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        NSString *target = PLUResolveTarget(O, dp, dp);
        BOOL toStdout = (O.outPath && [O.outPath isEqualToString:@"-"]);

        if ([fmt isEqualToString:@"xml1"] || [fmt isEqualToString:@"binary1"]) {
            NSPropertyListFormat wfmt;
            if ([fmt isEqualToString:@"xml1"]) wfmt = NSPropertyListXMLFormat_v1_0;
            else wfmt = NSPropertyListBinaryFormat_v1_0;
            BOOL ok = NO;
            NSData *d = PLUPropertyListData(obj, wfmt, &ok);
            if (!ok) {
                fprintf(stderr, "%s: Could not serialize property list\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            rc |= PLUWriteBinaryTarget(dp, target, toStdout, d);
        } else if ([fmt isEqualToString:@"json"]) {
            BOOL ok = NO;
            NSData *d = PLUJSONData(obj, O.pretty, &ok);
            if (!ok) {
                fprintf(stderr, "%s: Invalid object in plist for JSON format\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            rc |= PLUWriteBinaryTarget(dp, target, toStdout, d);
        } else if ([fmt isEqualToString:@"swift"]) {
            NSString *symbol = PLUSymbolForPath(dp);
            NSString *text = PLUSwiftText(obj, dp, symbol, PLUSwiftAnnotate(obj), YES);
            if (!text) {
                fprintf(stderr, "%s: Input contains an object that cannot be represented in Swift literal syntax\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            if (toStdout) {
                fputs([text UTF8String], stdout);
            } else {
                rc |= PLUWriteFileData(dp, target, [text dataUsingEncoding:NSUTF8StringEncoding]);
            }
        } else if ([fmt isEqualToString:@"objc"]) {
            NSString *symbol = PLUSymbolForPath(dp);
            NSString *importBase = (target && !toStdout) ? [target lastPathComponent] : nil;
            NSString *text = PLUObjCText(obj, dp, symbol, importBase);
            if (!text) {
                fprintf(stderr, "%s: Input contains an object that cannot be represented in Obj-C literal syntax\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
            if (toStdout) {
                fputs([text UTF8String], stdout);
            } else {
                rc |= PLUWriteFileData(dp, target, [text dataUsingEncoding:NSUTF8StringEncoding]);
                if (O.header) {
                    NSString *h = [target stringByDeletingPathExtension];
                    NSString *hpath = [h stringByAppendingPathExtension:@"h"];
                    NSString *htext = PLUObjCHeaderText(obj, dp, symbol);
                    rc |= PLUWriteFileData(dp, hpath, [htext dataUsingEncoding:NSUTF8StringEncoding]);
                }
            }
        }
    }
    return rc;
}

static int PLUHandleMutate(PLUOptions O, BOOL replace, BOOL remove, NSArray *pos, NSArray *files) {
    NSString *keyPath = [pos objectAtIndex:0];
    NSString *type = [pos count] > 1 ? [pos objectAtIndex:1] : nil;
    NSString *valueArg = [pos count] > 2 ? [pos objectAtIndex:2] : nil;
    id value = nil;
    if (!remove) {
        NSString *t = [type hasPrefix:@"-"] ? [type substringFromIndex:1] : type;
        if (!PLUValidInsertType(t)) {
            fprintf(stderr, "Unknown insert or replace type %s\n", [type UTF8String]);
            return 1;
        }
        value = PLUValueForType(t, valueArg);
    }
    int rc = 0;
    for (NSString *dp in files) {
        NSString *err = nil;
        NSData *data = PLUReadData(dp, &err);
        if (!data) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        NSPropertyListFormat pfmt;
        id root = PLUParseData(data, &pfmt, &err);
        if (!root) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        err = nil;
        if (remove) {
            if (PLUTreeremove(root, keyPath, &err) != 0) {
                fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
                rc = 1;
                continue;
            }
        } else {
            if (PLUTreemutate(root, keyPath, value, replace, O.append, &err) != 0) {
                fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
                rc = 1;
                continue;
            }
        }
        if (pfmt == NSPropertyListOpenStepFormat) {
            fprintf(stderr, "%s: Conversion to OpenStep format is not supported\n", [dp UTF8String]);
            rc = 1;
            continue;
        }
        NSData *out = nil;
        if (pfmt == (NSPropertyListFormat)PLU_JSON_FORMAT) {
            BOOL ok = NO;
            out = PLUJSONData(root, O.pretty, &ok);
            if (!ok) {
                fprintf(stderr, "%s: Invalid object in plist for JSON format\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
        } else {
            BOOL ok = NO;
            out = PLUPropertyListData(root, pfmt, &ok);
            if (!ok) {
                fprintf(stderr, "%s: Could not serialize property list\n", [dp UTF8String]);
                rc = 1;
                continue;
            }
        }
        NSString *target = PLUResolveTarget(O, dp, dp);
        BOOL toStdout = (O.outPath && [O.outPath isEqualToString:@"-"]);
        rc |= PLUWriteBinaryTarget(dp, target, toStdout, out);
    }
    return rc;
}

static int PLUHandleType(PLUOptions O, NSString *keyPath, NSArray *files) {
    int rc = 0;
    for (NSString *dp in files) {
        NSString *err = nil;
        NSData *data = PLUReadData(dp, &err);
        if (!data) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        NSPropertyListFormat pfmt;
        id root = PLUParseData(data, &pfmt, &err);
        if (!root) {
            fprintf(stderr, "%s: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        id v = PLUExtractValue(root, keyPath, &err);
        if (!v) {
            fprintf(stderr, "%s: Could not extract value, error: %s\n", [dp UTF8String], [err UTF8String]);
            rc = 1;
            continue;
        }
        if (O.expect) {
            NSString *want = PLUWantTypeName(O.expect);
            if (want && ![want isEqualToString:PLUTypeName(v)]) {
                fprintf(stderr, "%s: Value at [%s] expected to be %s but is %s\n",
                        [dp UTF8String], [keyPath UTF8String], [want UTF8String], [PLUTypeName(v) UTF8String]);
                rc = 1;
                continue;
            }
        }
        NSString *target = PLUResolveTarget(O, dp, nil);
        BOOL toStdout = (target == nil || [target isEqualToString:@"-"]);
        rc |= PLUHandleRawOrTypeOutput(PLUTypeName(v), O, toStdout, target, dp);
    }
    return rc;
}

static int PLUHandleCreate(NSString *fmt, NSString *target) {
    if (!PLUIsKnownFormat(fmt, NO)) {
        fprintf(stderr, "Unknown format specifier: %s\n", [fmt UTF8String]);
        return 1;
    }
    BOOL toStdout = [target isEqualToString:@"-"];
    id empty = [NSMutableDictionary dictionary];
    if ([fmt isEqualToString:@"json"]) {
        BOOL ok = NO;
        NSData *d = PLUJSONData(empty, NO, &ok);
        if (!ok) return 1;
        PLUWriteBinaryTarget(nil, target, toStdout, d);
        return 0;
    }
    if ([fmt isEqualToString:@"xml1"] || [fmt isEqualToString:@"binary1"]) {
        NSPropertyListFormat wfmt = ([fmt isEqualToString:@"xml1"]) ? NSPropertyListXMLFormat_v1_0 : NSPropertyListBinaryFormat_v1_0;
        BOOL ok = NO;
        NSData *d = PLUPropertyListData(empty, wfmt, &ok);
        if (!ok) return 1;
        PLUWriteBinaryTarget(nil, target, toStdout, d);
        return 0;
    }
    if ([fmt isEqualToString:@"swift"]) {
        NSData *d = [@"/// Generated from -\nlet - = [\n    ]" dataUsingEncoding:NSUTF8StringEncoding];
        PLUWriteBinaryTarget(nil, target, toStdout, d);
        return 0;
    }
    if ([fmt isEqualToString:@"objc"]) {
        NSData *d = [@"/// Generated from -\n__attribute__((visibility(\"hidden\")))\nNSDictionary * const _ = @{\n};" dataUsingEncoding:NSUTF8StringEncoding];
        PLUWriteBinaryTarget(nil, target, toStdout, d);
        return 0;
    }
    return 1;
}

int main(int argc, const char *argv[]) {
    @autoreleasepool {
        NSMutableArray *all = [NSMutableArray array];
        for (int i = 1; i < argc; i++) {
            NSString *s = [NSString stringWithUTF8String:argv[i]];
            if (s) [all addObject:s];
        }
        if (all.count == 0) {
            fprintf(stderr, "No files specified.\n");
            return 1;
        }

        NSUInteger idx = 0;
        int cmd = PLU_CMD_LINT;
        NSString *firstTok = [all objectAtIndex:0];
        if ([firstTok isEqualToString:@"-lint"]) { cmd = PLU_CMD_LINT; idx = 1; }
        else if ([firstTok isEqualToString:@"-help"]) { cmd = PLU_CMD_HELP; idx = 1; }
        else if ([firstTok isEqualToString:@"-convert"]) { cmd = PLU_CMD_CONVERT; idx = 1; }
        else if ([firstTok isEqualToString:@"-insert"]) { cmd = PLU_CMD_INSERT; idx = 1; }
        else if ([firstTok isEqualToString:@"-replace"]) { cmd = PLU_CMD_REPLACE; idx = 1; }
        else if ([firstTok isEqualToString:@"-remove"]) { cmd = PLU_CMD_REMOVE; idx = 1; }
        else if ([firstTok isEqualToString:@"-extract"]) { cmd = PLU_CMD_EXTRACT; idx = 1; }
        else if ([firstTok isEqualToString:@"-type"]) { cmd = PLU_CMD_TYPE; idx = 1; }
        else if ([firstTok isEqualToString:@"-create"]) { cmd = PLU_CMD_CREATE; idx = 1; }
        else if ([firstTok isEqualToString:@"-p"]) { cmd = PLU_CMD_PRINT; idx = 1; }
        else { cmd = PLU_CMD_LINT; idx = 0; }

        if (cmd == PLU_CMD_HELP) {
            fputs([PLUHelpText() UTF8String], stdout);
            return 0;
        }

        NSMutableArray *positional = [NSMutableArray array];
        if (cmd == PLU_CMD_CONVERT || cmd == PLU_CMD_CREATE) {
            if (idx >= all.count) {
                if (cmd == PLU_CMD_CREATE) {
                    fprintf(stderr, "'Create' requires a plist format.\n");
                } else {
                    fprintf(stderr, "Missing format specifier for command.\n");
                }
                return 1;
            }
            [positional addObject:[all objectAtIndex:idx]];
            idx++;
        } else if (cmd == PLU_CMD_INSERT || cmd == PLU_CMD_REPLACE) {
            if (all.count <= idx + 1) {
                fprintf(stderr, "'Insert' and 'Replace' require a key path, a type, and a value.\n");
                return 1;
            }
            [positional addObject:[all objectAtIndex:idx]];
            NSString *t = [all objectAtIndex:idx + 1];
            NSString *ts = [t hasPrefix:@"-"] ? [t substringFromIndex:1] : t;
            if (!PLUValidInsertType(ts)) {
                fprintf(stderr, "Unknown insert or replace type %s\n", [t UTF8String]);
                return 1;
            }
            [positional addObject:t];
            BOOL needsValue = !([ts isEqualToString:@"array"] || [ts isEqualToString:@"dictionary"]);
            if (needsValue && all.count <= idx + 2) {
                fprintf(stderr, "'Insert' and 'Replace' require a key path, a type, and a value2.\n");
                return 1;
            }
            if (needsValue) {
                [positional addObject:[all objectAtIndex:idx + 2]];
                idx += 3;
            } else {
                idx += 2;
            }
        } else if (cmd == PLU_CMD_REMOVE) {
            if (idx >= all.count) {
                fprintf(stderr, "'Remove' requires a key path.\n");
                return 1;
            }
            [positional addObject:[all objectAtIndex:idx]];
            idx++;
        } else if (cmd == PLU_CMD_EXTRACT) {
            if (all.count < idx + 2) {
                fprintf(stderr, "'Extract' requires a key path and a plist format.\n");
                return 1;
            }
            [positional addObject:[all objectAtIndex:idx]];
            [positional addObject:[all objectAtIndex:idx + 1]];
            idx += 2;
        } else if (cmd == PLU_CMD_TYPE) {
            if (idx >= all.count) {
                fprintf(stderr, "'Extract' requires a key path and a plist format.\n");
                return 1;
            }
            [positional addObject:[all objectAtIndex:idx]];
            idx++;
        }

        NSString *fmt = nil;
        if (cmd == PLU_CMD_CREATE || cmd == PLU_CMD_CONVERT) {
            fmt = [positional objectAtIndex:0];
            if (!PLUIsKnownFormat(fmt, NO)) {
                fprintf(stderr, "Unknown format specifier: %s\n", [fmt UTF8String]);
                return 1;
            }
        } else if (cmd == PLU_CMD_EXTRACT) {
            NSString *efmt = [positional objectAtIndex:1];
            if (!PLUIsKnownFormat(efmt, YES)) {
                fprintf(stderr, "Unknown format specifier: %s\n", [efmt UTF8String]);
                return 1;
            }
        }

        PLUOptions O;
        memset(&O, 0, sizeof(O));
        NSMutableArray *files = [NSMutableArray array];
        PLUOptMask mask = PLUMaskForCommand(cmd);

        for (; idx < all.count; idx++) {
            NSString *tok = [all objectAtIndex:idx];
            if ([tok isEqualToString:@"--"]) {
                for (idx++; idx < all.count; idx++) {
                    NSString *f = [all objectAtIndex:idx];
                    if ([f isEqualToString:@"-"] && cmd != PLU_CMD_CREATE) {
                        [files addObject:@"<stdin>"];
                    } else {
                        [files addObject:f];
                    }
                }
                break;
            }
            if (tok.length > 1 && [tok hasPrefix:@"-"]) {
                if ([tok isEqualToString:@"-s"] && (mask & PLU_OPT_s)) {
                    O.silent = YES;
                } else if ([tok isEqualToString:@"-o"] && (mask & PLU_OPT_o)) {
                    if (idx + 1 >= all.count) {
                        fprintf(stderr, "Missing argument for -o.\n");
                        return 1;
                    }
                    O.outPath = [all objectAtIndex:++idx];
                } else if ([tok isEqualToString:@"-e"] && (mask & PLU_OPT_e)) {
                    if (idx + 1 >= all.count) {
                        fprintf(stderr, "Missing argument for -e.\n");
                        return 1;
                    }
                    O.outExt = [all objectAtIndex:++idx];
                } else if ([tok isEqualToString:@"-r"] && (mask & PLU_OPT_r)) {
                    O.pretty = YES;
                } else if ([tok isEqualToString:@"-n"] && (mask & PLU_OPT_n)) {
                    O.noNL = YES;
                } else if ([tok isEqualToString:@"-header"] && (mask & PLU_OPT_header)) {
                    O.header = YES;
                } else if ([tok isEqualToString:@"-expect"] && (mask & PLU_OPT_expect)) {
                    if (idx + 1 >= all.count) {
                        fprintf(stderr, "-expect requires a type argument.\n");
                        return 1;
                    }
                    NSString *v = [all objectAtIndex:++idx];
                    if (!PLUValidExpect(v)) {
                        fprintf(stderr, "-expect type [%s] not valid.\n", [v UTF8String]);
                        return 1;
                    }
                    O.expect = v;
                } else if ([tok isEqualToString:@"-append"] && (mask & PLU_OPT_append)) {
                    O.append = YES;
                } else {
                    fprintf(stderr, "unrecognized option: %s\n", [tok UTF8String]);
                    return 1;
                }
            } else {
                if ([tok isEqualToString:@"-"] && cmd != PLU_CMD_CREATE) {
                    [files addObject:@"<stdin>"];
                } else {
                    [files addObject:tok];
                }
            }
        }

        if (files.count == 0) {
            fprintf(stderr, "No files specified.\n");
            return 1;
        }

        if (cmd == PLU_CMD_PRINT) {
            if (O.outPath) {
                fprintf(stderr, "-o is not used with -p.\n");
                return 1;
            }
            if (O.outExt) {
                fprintf(stderr, "-e is not used with -p.\n");
                return 1;
            }
            if (O.silent) {
                fprintf(stderr, "-s doesn't make a lot of sense with -p.\n");
            }
        }
        if (cmd == PLU_CMD_LINT) {
            if (O.outPath) {
                fprintf(stderr, "-o is not used with -lint.\n");
                return 1;
            }
            if (O.outExt) {
                fprintf(stderr, "-e is not used with -lint.\n");
                return 1;
            }
        }

        switch (cmd) {
            case PLU_CMD_CREATE:
                return PLUHandleCreate(fmt, [files objectAtIndex:0]);
            case PLU_CMD_LINT:
                return PLUHandleLint(O, files);
            case PLU_CMD_PRINT:
                return PLUHandlePrint(O, files);
            case PLU_CMD_CONVERT:
                return PLUHandleConvert(O, fmt, files);
            case PLU_CMD_INSERT:
            case PLU_CMD_REPLACE:
                return PLUHandleMutate(O, (cmd == PLU_CMD_REPLACE), NO, positional, files);
            case PLU_CMD_REMOVE:
                return PLUHandleMutate(O, NO, YES, positional, files);
            case PLU_CMD_EXTRACT:
                return PLUHandleExtract(O, [positional objectAtIndex:0], [positional objectAtIndex:1], files);
            case PLU_CMD_TYPE:
                return PLUHandleType(O, [positional objectAtIndex:0], files);
            default:
                return 0;
        }
    }
}